import traceback

import pytest

import attrs


def test_frozen_exception_allows_traceback_reassignment():
    """
    Regression test: setting __traceback__ on a frozen exception instance
    (as Python's exception machinery does automatically, e.g. when raised
    inside a context manager, or when manually re-raising) must not raise
    FrozenInstanceError.
    """

    @attrs.frozen
    class MyException(Exception):
        pass

    try:
        raise MyException()
    except MyException as e:
        # This mimics what Python's exception machinery does internally
        # (and what users do when manually re-raising exceptions).
        e.__traceback__ = e.__traceback__


def test_frozen_exception_traceback_survives_context_manager():
    from contextlib import contextmanager

    @attrs.frozen
    class MyException(Exception):
        pass

    @contextmanager
    def do_nothing():
        yield

    caught = None
    try:
        with do_nothing():
            raise MyException("boom")
    except MyException as e:
        caught = e

    assert caught is not None
    # Should be able to format the traceback without errors.
    traceback.format_exception(type(caught), caught, caught.__traceback__)

import json
import threading

import pytest

from boltons.jsonutils import JSONLIterator


def _run_with_timeout(fn, timeout=5):
    """Run fn() in a daemon thread and return its result, or raise
    TimeoutError if it doesn't complete within `timeout` seconds.

    Using a daemon thread means that even if `fn` hangs forever (as in
    the bug under test), this helper - and the test process - will not
    itself hang waiting for the thread to finish.
    """
    result = {}

    def target():
        try:
            result['value'] = fn()
        except BaseException as e:  # noqa
            result['error'] = e

    t = threading.Thread(target=target, daemon=True)
    t.start()
    t.join(timeout)
    if t.is_alive():
        raise TimeoutError("function did not complete within %s seconds" % timeout)
    if 'error' in result:
        raise result['error']
    return result.get('value')


def test_rel_seek_into_last_line_without_trailing_newline_does_not_hang(tmp_path):
    # File with no trailing newline; rel_seek lands inside the last line.
    path = tmp_path / "no_trailing_newline.jsonl"
    path.write_text('{"1": 1}\n{"2": 2}')

    def run():
        with open(str(path)) as f:
            it = JSONLIterator(f, rel_seek=0.9)
            return list(it)

    try:
        result = _run_with_timeout(run, timeout=5)
    except TimeoutError:
        pytest.fail(
            "JSONLIterator hung forever when rel_seek landed inside the "
            "last line of a file without a trailing newline"
        )
    except ValueError:
        # A clear, immediate error is an acceptable outcome per the
        # bug report ("or to raise a clear error for the bad seek value").
        return

    # If it didn't raise, it must have completed and returned a list
    # (not hung, not raised something obscure).
    assert isinstance(result, list)


def test_negative_rel_seek_seeks_from_the_end(tmp_path):
    # Negative rel_seek should behave like negative indexing: it should
    # seek relative to the end of the file, not past the end of the file.
    path = tmp_path / "normal.jsonl"
    n = 20
    objs = [{"idx": i} for i in range(n)]
    with open(str(path), "w") as f:
        for o in objs:
            f.write(json.dumps(o) + "\n")

    def run(rel_seek):
        def _run():
            with open(str(path)) as f:
                it = JSONLIterator(f, rel_seek=rel_seek)
                return list(it)
        return _run_with_timeout(_run, timeout=5)

    # Baseline: a positive rel_seek equivalent to "30% into the file"
    try:
        positive_result = run(0.3)
    except TimeoutError:
        pytest.fail("baseline rel_seek=0.3 unexpectedly hung")

    # -0.7 should be equivalent to seeking to 1.0 - 0.7 == 0.3 from the
    # start (i.e., seeking from the end, like negative indices).
    try:
        negative_result = run(-0.7)
    except TimeoutError:
        pytest.fail(
            "JSONLIterator hung with a negative rel_seek value; negative "
            "rel_seek should seek relative to the end of the file, not "
            "past the end of it"
        )

    assert negative_result == positive_result
    # Sanity: should not have consumed all the lines nor zero lines,
    # given that rel_seek=0.3 is neither the very start nor the very end.
    assert 0 < len(negative_result) < n

"""
Regression test for: parse_wheel_filename / parse_sdist_filename should
raise InvalidWheelFilename / InvalidSdistFilename (not InvalidVersion) when
the filename contains a bogus version string.
"""
import pytest

from packaging.utils import (
    InvalidSdistFilename,
    InvalidWheelFilename,
    parse_sdist_filename,
    parse_wheel_filename,
)
from packaging.version import InvalidVersion


def test_parse_wheel_filename_bogus_version_raises_invalid_wheel_filename():
    with pytest.raises(InvalidWheelFilename):
        parse_wheel_filename("foobar-1.x-py3-none-any.whl")


def test_parse_wheel_filename_bogus_version_does_not_raise_invalid_version():
    try:
        parse_wheel_filename("foobar-1.x-py3-none-any.whl")
    except InvalidVersion:
        pytest.fail(
            "parse_wheel_filename raised InvalidVersion instead of "
            "InvalidWheelFilename"
        )
    except InvalidWheelFilename:
        pass


def test_parse_sdist_filename_bogus_version_raises_invalid_sdist_filename():
    with pytest.raises(InvalidSdistFilename):
        parse_sdist_filename("foo-1.x.tar.gz")


def test_parse_sdist_filename_bogus_version_does_not_raise_invalid_version():
    try:
        parse_sdist_filename("foo-1.x.tar.gz")
    except InvalidVersion:
        pytest.fail(
            "parse_sdist_filename raised InvalidVersion instead of "
            "InvalidSdistFilename"
        )
    except InvalidSdistFilename:
        pass

"""Regression test for `Version.replace()` not preserving subclass type.

Bug report: calling `.replace()` on an instance of a Version subclass
falls back to plain `Version` instead of returning an instance of the
subclass, losing subclass-specific behaviour (e.g. custom __str__).
"""

import pytest

from semver import Version


class SemVerWithVPrefix(Version):
    @classmethod
    def parse(cls, version, optional_minor_and_patch=True):
        if version[0] not in ("v", "V"):
            raise ValueError("must start with v or V")
        return super().parse(version[1:], optional_minor_and_patch=True)

    def __str__(self):
        return "v" + super().__str__()


def test_replace_returns_subclass_instance():
    version = SemVerWithVPrefix.parse("v1.1.0")
    dev_version = version.replace(prerelease="dev.0")

    assert isinstance(dev_version, SemVerWithVPrefix), (
        f"Expected replace() to return an instance of {SemVerWithVPrefix!r}, "
        f"but got {type(dev_version)!r}"
    )
    assert str(dev_version) == "v1.1.0-dev.0"


def test_replace_preserves_subclass_type_generic():
    class MyVersion(Version):
        pass

    v = MyVersion(1, 2, 3)
    replaced = v.replace(major=2)
    assert isinstance(replaced, MyVersion)
    assert replaced.major == 2


if __name__ == "__main__":
    raise SystemExit(pytest.main([__file__, "-v"]))
